   [57]={next_id=58, abreast_id={}, pType =1, cg_type =0, dialog=1, msg="Fragments. From when I became a Star Knight. Hard to describe… As a stellar mage, I trust my memory, but sometimes dreams hold more truth.", msg_color="", msg_size=0, talker="Lumen", audio="", img="arts/ui/bg/story/storybg_901.jpg", video_url="", music_id=0, background_music="", model_tid={{ 2, "4509", 0, 0}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, update_model={{ 2,1}}, role_act={}, head_path="", flash_time=0, shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [58]={next_id=59, abreast_id={}, pType =1, cg_type =0, dialog=1, msg="The Starcall Abbey oversees the Star Knight inauguration. No one suspects them of tampering—not even with memories.", msg_color="", msg_size=0, talker="Lumen", audio="", img="arts/ui/bg/story/storybg_901.jpg", video_url="", music_id=0, background_music="", model_tid={{ 2, "4509", 0, 0}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, update_model={{ 2,1}}, role_act={}, head_path="", flash_time=0, shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [59]={next_id=60, abreast_id={}, pType =1, cg_type =0, dialog=1, msg="Yet here I am, forced to consider them suspects.", msg_color="", msg_size=0, talker="Lumen", audio="", img="arts/ui/bg/story/storybg_901.jpg", video_url="", music_id=0, background_music="", model_tid={{ 2, "4509", 0, 0}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, update_model={{ 2,1}}, role_act={}, head_path="", flash_time=0, shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [60]={next_id=61, abreast_id={}, pType =1, cg_type =0, dialog=1, msg="If this gets out, you'll be branded a heretic. That it?", msg_color="", msg_size=0, talker="Centaurea", audio="", img="arts/ui/bg/story/storybg_901.jpg", video_url="", music_id=0, background_music="", model_tid={{ 2, "2504", 0, 0}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, update_model={{ 2,1}}, role_act={}, head_path="", flash_time=0, shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [61]={next_id=62, abreast_id={}, pType =1, cg_type =0, dialog=1, msg="The Abbey doesn't speak for our Lord of Stars.", msg_color="", msg_size=0, talker="Lumen", audio="", img="arts/ui/bg/story/storybg_901.jpg", video_url="", music_id=0, background_music="", model_tid={{ 2, "4509", 0, 0}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, update_model={{ 2,1}}, role_act={}, head_path="", flash_time=0, shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [62]={next_id=63, abreast_id={}, pType =1, cg_type =0, dialog=1, msg="But their methods… To my shame, despite years of dealings, we've barely scratched the surface.", msg_color="", msg_size=0, talker="Lumen", audio="", img="arts/ui/bg/story/storybg_901.jpg", video_url="", music_id=0, background_music="", model_tid={{ 2, "4509", 0, 0}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, update_model={{ 2,1}}, role_act={}, head_path="", flash_time=0, shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [63]={next_id=64, abreast_id={}, pType =1, cg_type =0, dialog=1, msg="You two, though? They can't influence you. You could uncover what I can't.", msg_color="", msg_size=0, talker="Lumen", audio="", img="arts/ui/bg/story/storybg_901.jpg", video_url="", music_id=0, background_music="", model_tid={{ 2, "4509", 0, 0}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, update_model={{ 2,1}}, role_act={}, head_path="", flash_time=0, shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
